			if (args) {
				ZEND_ASSERT(args->kind == ZEND_AST_ARG_LIST);

				zend_bool uses_named_args = 0;
				for (j = 0; j < args->children; j++) {
					zend_ast **arg_ast_ptr = &args->child[j];
					zend_ast *arg_ast = *arg_ast_ptr;

